#pragma once

#include <PlotThread.h>
#include <SkyrimNetAPI.h>

#include <chrono>
#include <string>
#include <vector>

// DecisionProbe — one fixed decision request, sent on demand from the Plots
// tab, whose answer settles what plot planning may assume about SkyrimNet's
// decision API before anything is built on it.
//
// The template (prompts/decisions/narrative_engine/probe.prompt) asks three
// questions, each with a known right answer:
//
//   capital   twenty options generated by an Inja loop, keys c1..c20, the
//             right one placed mid-list so position is no help
//   fish      five options written out by hand, keys c1..c5
//   cold      a yes/no
//
// Between them they answer the five things Phase 17 Milestone 2 Step 2 lists:
// whether loop-generated criteria render, whether keys come back verbatim,
// whether twenty options fare as well as five, whether one request answers
// several questions, and how long a request takes.
namespace NarrativeEngine::DecisionProbe
{
    inline constexpr const char* kTemplate = "narrative_engine/probe";

    // The capital question's options, in the order they are offered, and the
    // key of the right one.
    [[nodiscard]] const std::vector<std::string>& Places();
    inline constexpr const char* kCapitalKey = "c13";
    inline constexpr const char* kFishKey = "c3";

    // The request's context: the place options as { key, label } rows.
    [[nodiscard]] std::string Context();

    struct Verdict
    {
        bool answered = false;      // the request came back at all
        bool loopRendered = false;  // the capital question was answered from its generated options
        bool keysVerbatim = false;  // every choice is one of the keys offered
        bool twentyCorrect = false; // the right place, out of twenty
        bool fiveCorrect = false;   // the right animal, out of five
        bool allQuestionsAnswered = false;
        long long latencyMs = 0;
        std::vector<std::string> lines; // what Run logs, one line per finding
    };

    // Pure: judges one result. Exposed so the reading of a result can be
    // checked without a round trip.
    [[nodiscard]] Verdict Judge(const SkyrimNetAPI::DecisionResult& result, std::chrono::milliseconds latency);

    // Sends the probe, waits, and logs the verdict. Plot worker only, because
    // the request blocks and nothing else waits on that thread.
    Verdict Run(const PlotThread::Token& pt);
} // namespace NarrativeEngine::DecisionProbe
